def split_herds_into_segments(apps, schema_editor):
    """Segments are business areas, not herds: bovinos → gado de corte + pecuária leiteira,
    suinos → suinocultura. Catalog, contracted items, discounts and coupons follow the new codes."""
    PlanSegment = apps.get_model("billing", "PlanSegment")
    PlanTier = apps.get_model("billing", "PlanTier")
    SubscriptionItem = apps.get_model("billing", "SubscriptionItem")
    SubscriptionDiscount = apps.get_model("billing", "SubscriptionDiscount")
    Coupon = apps.get_model("billing", "Coupon")

    swine = PlanSegment.objects.filter(code="suinos").first()
    if swine and not PlanSegment.objects.filter(code="suinocultura").exists():
        swine.code, swine.name, swine.subtitle = "suinocultura", "Suinocultura", "Ciclo completo e terminação"
        swine.save(update_fields=["code", "name", "subtitle"])
    cattle = PlanSegment.objects.filter(code="bovinos").first()
    if cattle and not PlanSegment.objects.filter(code="gado-de-corte").exists():
        cattle.code, cattle.name, cattle.subtitle = "gado-de-corte", "Gado de corte", "Cria, recria e engorda"
        cattle.description = "Rebanho, lotes, pastagens, tratos, reprodução, sanidade e custos do gado de corte."
        cattle.save(update_fields=["code", "name", "subtitle", "description"])
    dairy, created = PlanSegment.objects.get_or_create(
        code="pecuaria-leiteira",
        defaults={
            "name": "Pecuária leiteira", "subtitle": "Produção de leite", "icon": "milk", "metric_label": "vacas em lactação",
            "description": "Rebanho leiteiro, ordenhas, tanques, qualidade do leite, reprodução e sanidade.",
            "image_path": "/landing-livestock.png", "sort_order": 25,
        },
    )
    if created or not dairy.tiers.exists():
        PlanTier.objects.create(segment=dairy, label="Sob consulta", requires_quote=True, sort_order=10)
    for code, order in (("plantacoes", 10), ("gado-de-corte", 20), ("pecuaria-leiteira", 25), ("suinocultura", 30), ("area-veterinario", 40)):
        PlanSegment.objects.filter(code=code).update(sort_order=order)

    dairy_tier = dairy.tiers.filter(is_active=True).order_by("sort_order").first()
    for item in SubscriptionItem.objects.filter(segment_code="suinos"):
        item.segment_code, item.segment_name = "suinocultura", "Suinocultura"
        item.save(update_fields=["segment_code", "segment_name"])
    for item in SubscriptionItem.objects.filter(segment_code="bovinos"):
        # Whoever had cattle keeps both cattle areas (same access as before the split).
        item.segment_code, item.segment_name = "gado-de-corte", "Gado de corte"
        item.save(update_fields=["segment_code", "segment_name"])
        if dairy_tier and not SubscriptionItem.objects.filter(subscription=item.subscription, segment_code="pecuaria-leiteira").exists():
            SubscriptionItem.objects.create(
                subscription=item.subscription, tier=dairy_tier, segment_code="pecuaria-leiteira", segment_name=dairy.name,
                segment_subtitle=dairy.subtitle, tier_label=dairy_tier.label, monthly_price=dairy_tier.monthly_price,
                discount_percent=0, final_monthly_price=dairy_tier.monthly_price, is_active=item.is_active,
            )
    for model in (SubscriptionDiscount, Coupon):
        model.objects.filter(segment_code="suinos").update(segment_code="suinocultura")
        model.objects.filter(segment_code="bovinos").update(segment_code="gado-de-corte")


